using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

public class EvaluationTests : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder _builder = null!;
    private DistributedApplication _app = null!;

    public async ValueTask InitializeAsync()
    {
        _builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _builder.BuildAsync();
        await _app.StartAsync();
    }

    public async ValueTask DisposeAsync()
    {
        await _app.DisposeAsync();
    }

    [Fact]
    public async Task ChatRespondsRelevantly()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.NotEmpty(responseText);
        Assert.Contains("Paris", responseText, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task EvaluateResponseQuality()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what cloud computing is in one paragraph.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.NotEmpty(responseText);

        // Evaluate using built-in quality metrics
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
        };

        var chatTurn = new ChatTurn(messages, response.Messages);
        var evaluatorContext = new EvaluatorContext(chatTurn, chatClient);

        foreach (var evaluator in evaluators)
        {
            var results = await evaluator.EvaluateAsync(evaluatorContext);
            foreach (var result in results)
            {
                Assert.True(
                    result.Value is NumericMetricValue { Value: >= 3 },
                    $"Metric '{result.Key}' scored below threshold.");
            }
        }
    }
}

